// Generates src/tokens/atlassian/*.generated.ts from @atlaskit/tokens (Apache-2.0).
// The generated files are committed, so the published package has no runtime dependency on Atlaskit.
// Run with: yarn sync-tokens
import { createRequire } from 'node:module';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'src/tokens/atlassian');
const { version } = require('@atlaskit/tokens/package.json');

const load = (name) =>
  require(`@atlaskit/tokens/dist/cjs/artifacts/tokens-raw/${name}.js`).default.filter(
    (t) => t.attributes?.state === 'active',
  );

const px = (value) => {
  const match = /^(-?\d+(?:\.\d+)?)px$/.exec(String(value));
  if (!match) throw new Error(`Expected a px value, got ${value}`);
  return Number(match[1]);
};

const ms = (value) => Number(String(value).replace('ms', ''));

const bezier = (value) => {
  const match = /^cubic-bezier\(([^)]+)\)$/.exec(String(value));
  return match ? match[1].split(',').map((n) => Number(n.trim())) : null;
};

const header = `// Generated by scripts/sync-atlassian-tokens.mjs from @atlaskit/tokens@${version} (Apache-2.0).\n// Do not edit by hand. Run \`yarn sync-tokens\` to regenerate.\n\n`;

function write(file, body) {
  writeFileSync(join(outDir, file), header + body);
  console.log(`wrote src/tokens/atlassian/${file}`);
}

mkdirSync(outDir, { recursive: true });

// Colors: semantic color and surface tokens only (charts, AI accents and shadows are out of scope for now).
const COLOR_PREFIX =
  /^(color\.(background|border|text|icon|link|interaction|skeleton|blanket)|elevation\.surface)(\.|$)/;
const colorMap = (theme) =>
  Object.fromEntries(
    load(theme)
      .filter((t) => COLOR_PREFIX.test(t.cleanName))
      .map((t) => [t.cleanName, String(t.value).toUpperCase()]),
  );
const light = colorMap('atlassian-light');
const dark = colorMap('atlassian-dark');
const missing = Object.keys(light).filter((k) => !(k in dark));
if (missing.length) throw new Error(`Dark theme is missing: ${missing.join(', ')}`);
const opacity = Object.fromEntries(
  load('atlassian-light')
    .filter((t) => t.cleanName.startsWith('opacity.'))
    .map((t) => [t.cleanName.replace('opacity.', ''), Number(t.value)]),
);
write(
  'colors.generated.ts',
  `export const atlassianLightColors = ${JSON.stringify(light, null, 2)} as const;\n\n` +
    `export type ColorToken = keyof typeof atlassianLightColors;\n\n` +
    `export const atlassianDarkColors: Record<ColorToken, string> = ${JSON.stringify(
      Object.fromEntries(Object.keys(light).map((k) => [k, dark[k]])),
      null,
      2,
    )};\n\n` +
    `export const atlassianOpacity = ${JSON.stringify(opacity, null, 2)} as const;\n`,
);

// Brand: which color tokens Atlassian derives from its Blue palette, and the Blue ramp itself.
// createTheme({ brand }) regenerates that ramp from the user's brand color and re-applies it here.
// Only brand, selection, focus and link roles follow the brand; accent and information blues stay blue.
const BRAND_ROLE = /\.(brand|selected|focused)(\.|$)|^color\.link(\.pressed)?$/;
const brandSteps = (theme) =>
  Object.fromEntries(
    load(theme)
      .filter(
        (t) =>
          COLOR_PREFIX.test(t.cleanName) &&
          BRAND_ROLE.test(t.cleanName) &&
          /^Blue\d+$/.test(t.original?.value ?? ''),
      )
      .map((t) => [t.cleanName, t.original.value.replace('Blue', '')]),
  );
const blueRamp = {};
for (const theme of ['atlassian-light', 'atlassian-dark']) {
  for (const t of load(theme)) {
    const step = /^Blue(\d+)$/.exec(t.original?.value ?? '')?.[1];
    if (step) blueRamp[step] = String(t.value).toUpperCase();
  }
}
write(
  'brand.generated.ts',
  `import type { ColorToken } from './colors.generated';\n\n` +
    `/** Atlassian's Blue ramp, keyed by palette step. Used as the lightness profile for brand ramps. */\n` +
    `export const atlassianBlueRamp = ${JSON.stringify(
      Object.fromEntries(Object.entries(blueRamp).sort(([a], [b]) => Number(a) - Number(b))),
      null,
      2,
    )} as const;\n\n` +
    `export type BrandStep = keyof typeof atlassianBlueRamp;\n\n` +
    `/** Color tokens that use a brand (Blue) palette step, per mode. */\n` +
    `export const atlassianBrandTokens: Record<'light' | 'dark', Partial<Record<ColorToken, BrandStep>>> = ${JSON.stringify(
      { light: brandSteps('atlassian-light'), dark: brandSteps('atlassian-dark') },
      null,
      2,
    )};\n`,
);

// Spacing: `space.100` -> space['100'] = 8. Negative values keep a `negative.` prefix.
const space = Object.fromEntries(
  load('atlassian-spacing').map((t) => [t.cleanName.replace('space.', ''), px(t.value)]),
);
write(
  'spacing.generated.ts',
  `export const atlassianSpace = ${JSON.stringify(space, null, 2)} as const;\n`,
);

// Shape: radii and border widths (percentage radii such as radius.tile are skipped).
const shape = load('atlassian-shape');
const radius = Object.fromEntries(
  shape
    .filter((t) => t.cleanName.startsWith('radius.') && String(t.value).endsWith('px'))
    .map((t) => [t.cleanName.replace('radius.', ''), px(t.value)]),
);
const borderWidth = Object.fromEntries(
  shape
    .filter((t) => t.cleanName.startsWith('border.width'))
    .map((t) => [t.cleanName.replace(/^border\.width\.?/, '') || 'default', px(t.value)]),
);
write(
  'shape.generated.ts',
  `export const atlassianRadius = ${JSON.stringify(radius, null, 2)} as const;\n\n` +
    `export const atlassianBorderWidth = ${JSON.stringify(borderWidth, null, 2)} as const;\n`,
);

// Typography: parse the CSS `font` shorthand ("normal 653 32px/36px <family>") into numbers.
const typography = load('atlassian-typography');
const textStyles = {};
const families = {};
for (const t of typography) {
  const name = t.cleanName.replace('font.', '');
  const value = String(t.value);
  const shorthand = /^\w+ (\d+) (\d+)px\/(\d+)px (.+)$/.exec(value);
  if (shorthand) {
    textStyles[name] = {
      fontWeight: Number(shorthand[1]),
      fontSize: Number(shorthand[2]),
      lineHeight: Number(shorthand[3]),
    };
  } else if (name.startsWith('family.')) {
    families[name.replace('family.', '')] = value;
  }
}
write(
  'typography.generated.ts',
  `export const atlassianTextStyles = ${JSON.stringify(textStyles, null, 2)} as const;\n\n` +
    `/** CSS font-family stacks. Native apps fall back to the system font unless a theme sets one. */\n` +
    `export const atlassianFontFamilies = ${JSON.stringify(families, null, 2)} as const;\n`,
);

// Motion: durations (ms), cubic-bezier easings as [x1, y1, x2, y2], and per-interaction specs.
const motion = load('atlassian-motion');
const durations = {};
const easings = {};
const interactions = {};
for (const t of motion) {
  const name = t.cleanName.replace('motion.', '');
  if (name.startsWith('duration.')) durations[name.replace('duration.', '')] = ms(t.value);
  else if (name.startsWith('easing.')) {
    const curve = bezier(t.value);
    if (curve) easings[name.replace('easing.', '')] = curve;
  } else if (t.value && typeof t.value === 'object' && 'duration' in t.value) {
    const curve = bezier(t.value.curve);
    if (curve) interactions[name] = { duration: Number(t.value.duration), easing: curve };
  }
}
write(
  'motion.generated.ts',
  `export const atlassianDurations = ${JSON.stringify(durations, null, 2)} as const;\n\n` +
    `export type Bezier = readonly [number, number, number, number];\n\n` +
    `export const atlassianEasings = ${JSON.stringify(easings, null, 2)} as const satisfies Record<string, Bezier>;\n\n` +
    `export const atlassianInteractions = ${JSON.stringify(interactions, null, 2)} as const;\n`,
);
